-- Integration assertions run against the installed schema; every fixture rolls back.
begin;
do $$
declare e uuid; a uuid; q jsonb; q2 jsonb; b public.bookings; b2 public.bookings; session uuid:=gen_random_uuid(); guests jsonb; actual numeric; rejected boolean; admin_id uuid; entry uuid;
begin
 insert into public.events(slug,title,price_egp,booking_fee_egp,starts_at,capacity,is_published,booking_mode)
 values('campus-test-'||gen_random_uuid(),'Campus integration fixture',1000,35,'2026-10-30 19:00:00+02',300,true,'booking') returning id into e;
 insert into public.event_sales_rules select e,price_tiers,discount_tiers,commission_tiers from public.event_sales_rules r join public.events ev on ev.id=r.event_id where ev.slug='halloween-party-2026';
 insert into public.campus_ambassadors(event_id,name,email,phone) values(e,'Test ambassador','campus-'||gen_random_uuid()||'@example.test','01000000000') returning id into a;
 insert into public.ambassador_codes(event_id,ambassador_id,code) values(e,a,'TEST01');
 q:=public.reserve_event_quote(e,session,51,null);
 assert (q->>'originalSubtotal')::numeric=51200,'Crossing price tier must split 50 x 1000 + 1 x 1200';
 assert (q->>'fees')::numeric=1785,'Booking fee must remain separate';
 assert (q->>'discountPercent')::numeric=0,'No code means no discount';
 q2:=public.reserve_event_quote(e,session,51,null);
 assert q2->>'id'=q->>'id','Repeated quote must be idempotent';
 q:=public.reserve_event_quote(e,session,9,'test01');
 assert (q->>'originalSubtotal')::numeric=9000,'Replacing a hold must release its inventory';
 assert (q->>'discountPercent')::numeric=10,'Nine tickets receive 10 percent';
 assert (q->>'total')::numeric=8415,'Discount excludes booking fees';
 select jsonb_agg(jsonb_build_object('name','Test Guest '||i,'phone','01000000000','gender','woman','dateOfBirth','2005-01-01')) into guests from generate_series(1,9) i;
 perform public.submit_campus_event_booking((q->>'id')::uuid,session,session,'booking-'||session||'@example.test',guests,'paymob',null,true);
 select * into b from public.bookings where event_quote_id=(q->>'id')::uuid;
 assert b.total_amount=8415 and b.ambassador_id=a,'Booking must use the saved quote';
 perform public.submit_campus_event_booking((q->>'id')::uuid,session,session,'booking-'||session||'@example.test',guests,'paymob',null,true);
 assert (select count(*) from public.bookings where event_quote_id=(q->>'id')::uuid)=1,'Checkout retry must not duplicate a booking';
 assert (select count(*) from public.ambassador_commissions where booking_id=b.id)=0,'Unpaid bookings must not accrue';
 insert into storage.objects(bucket_id,name) values('payment-proofs','pending/2026-10/12345678-1234-4234-8234-123456789012.png');
 perform public.attach_event_receipt(b.payment_token,'instapay','pending/2026-10/12345678-1234-4234-8234-123456789012.png');
 perform public.attach_event_receipt(b.payment_token,'instapay','pending/2026-10/12345678-1234-4234-8234-123456789012.png');
 assert (select count(*) from public.payments where booking_id=b.id)=1,'Receipt retry must not duplicate payment';
 assert (select amount from public.payments where booking_id=b.id)=8415,'Receipt must use the saved exact total';
 update public.payments set status='recorded' where booking_id=b.id;
 update public.bookings set status='confirmed',amount_paid=total_amount where id=b.id;
 assert (select sum(amount) from public.ambassador_commissions where booking_id=b.id)=450,'First nine commissions use original price x 5 percent';
 update public.bookings set amount_paid=total_amount where id=b.id;
 assert (select count(*) from public.ambassador_commissions where booking_id=b.id)=9,'Duplicate confirmation must not duplicate commission';
 session:=gen_random_uuid();q2:=public.reserve_event_quote(e,session,16,'TEST01');
 assert (q2->>'discountPercent')::numeric=30,'Fifteen plus tickets receive 30 percent';
 select jsonb_agg(jsonb_build_object('name','Test Guest '||i,'phone','01000000000','gender','woman','dateOfBirth','2005-01-01')) into guests from generate_series(1,16) i;
 perform public.submit_campus_event_booking((q2->>'id')::uuid,session,session,'booking-'||session||'@example.test',guests,'paymob',null,true);
 select * into b2 from public.bookings where event_quote_id=(q2->>'id')::uuid;
 update public.bookings set status='confirmed',amount_paid=total_amount where id=b2.id;
 assert (select sum(amount) from public.ambassador_commissions where booking_id=b2.id)=1650,'Positions 10-14 7.5%, 15-19 10%, 20-24 12.5%, 25 15%';
 assert (select sum(amount) from public.ambassador_commissions where booking_id=b.id)=450,'Tier advancement must not recalculate old commissions';
 update public.bookings set status='cancelled' where id=b2.id;
 assert (select count(*) from public.ambassador_commissions where booking_id=b2.id and not is_void)=0,'Cancellation voids commission';
 update public.bookings set status='confirmed' where id=b2.id;
 assert (select sum(amount) from public.ambassador_commissions where booking_id=b2.id and not is_void)=1650,'Restoring confirmation restores original ledger';
 rejected:=false;begin update public.bookings set total_amount=1 where id=b.id; exception when others then rejected:=true;end;
 assert rejected,'Historical prices must be immutable';
 update public.event_sales_rules set price_tiers='[{"from":1,"price":2000}]' where event_id=e;
 assert (select total_amount from public.bookings where id=b.id)=8415,'Rule edit must preserve saved bookings';
 session:=gen_random_uuid();q:=public.reserve_event_quote(e,session,1,'TEST01');
 assert (q->>'discountPercent')::numeric=5,'Individual code booking gets five percent';
 guests:='[{"name":"Test Guest","phone":"01000000000","gender":"woman","dateOfBirth":"2005-01-01"}]';
 update public.event_price_quotes set expires_at=now()-interval '1 second' where id=(q->>'id')::uuid;
 rejected:=false;begin perform public.submit_campus_event_booking((q->>'id')::uuid,session,session,'expired@example.test',guests,'paymob',null,true);exception when others then rejected:=true;end;
 assert rejected,'Expired quote must be rejected before payment';
 update public.events set capacity=25 where id=e;
 rejected:=false;begin perform public.reserve_event_quote(e,gen_random_uuid(),1,null);exception when others then rejected:=true;end;
 assert rejected,'Capacity must include existing pending and confirmed bookings';
 update public.events set capacity=300 where id=e;
 session:=gen_random_uuid();q:=public.reserve_event_quote(e,session,1,'TEST01');
 guests:='[{"name":"Test Guest","phone":"01000000000"}]';
 perform public.submit_campus_event_booking((q->>'id')::uuid,session,session,'no-demographics-'||session||'@example.test',guests,'paymob',null,true);
 assert exists(select 1 from public.bookings where event_quote_id=(q->>'id')::uuid),'Code booking must work with name and phone only';
 session:=gen_random_uuid();q:=public.reserve_event_quote(e,session,2,'TEST01');
 guests:='[{"name":"Test Guest","phone":"01000000000","gender":"man","dateOfBirth":"2007-01-01"},{"name":"Test Guest Two","phone":"01000000000","gender":"woman","dateOfBirth":"2007-01-01"}]';
 perform public.submit_campus_event_booking((q->>'id')::uuid,session,session,'couple-'||session||'@example.test',guests,'paymob',null,true);
 session:=gen_random_uuid();q:=public.reserve_event_quote(e,session,2,null);
 guests:='[{"name":"Test Guest","phone":"01000000000"},{"name":"Test Guest Two","phone":"01000000000"}]';
 rejected:=false;begin perform public.submit_campus_event_booking((q->>'id')::uuid,session,session,'general@example.test',guests,'paymob',null,false);exception when others then rejected:=true;end;
 assert rejected,'Admission and policy acknowledgement remains required';
 perform public.submit_campus_event_booking((q->>'id')::uuid,session,session,'general-'||session||'@example.test',guests,'paymob',null,true);
 assert exists(select 1 from public.bookings where event_quote_id=(q->>'id')::uuid),'Ordinary booking must work without demographic fields';
 update public.campus_ambassadors set is_active=false where id=a;
 rejected:=false;begin perform public.reserve_event_quote(e,gen_random_uuid(),1,'TEST01');exception when others then rejected:=true;end;
 assert rejected,'Inactive ambassadors must not validate';
 update public.campus_ambassadors set is_active=true where id=a;
 assert not has_function_privilege('anon','public.reserve_event_quote(uuid,uuid,integer,text)','execute'),'Anonymous role must not call privileged writer';
 assert not has_function_privilege('authenticated','public.submit_campus_event_booking(uuid,uuid,uuid,text,jsonb,text,jsonb,boolean)','execute'),'Ordinary users must not call privileged checkout';
 select id into admin_id from public.admin_users where is_active and role='admin' limit 1;
 perform set_config('request.jwt.claim.sub',admin_id::text,true);
 entry:=public.issue_ambassador_entry(a);
 assert entry=public.issue_ambassador_entry(a),'Free entry must be one per ambassador';
 assert (select total_amount from public.bookings where payment_token=entry)=0,'Free entry must have zero price and fees';
 assert (select count(*) from public.ambassador_commissions where booking_id=(select id from public.bookings where payment_token=entry))=0,'Free entry earns no commission';
 perform public.save_campus_ambassador(null,e,'Demo Leader One','FOFA','','',null,true,'FOFA');
 perform public.save_campus_ambassador(null,e,'Demo Leader Two','FOFA','','',null,true,'FOFA');
 assert (select count(*) from public.ambassador_codes where event_id=e and code in ('FOFA-A','FOFA-B'))=2,'Panel generator must allocate short distinct letter codes';
 update public.ambassador_codes set is_active=false where event_id=e and code='FOFA-A';
 perform public.save_campus_ambassador(null,e,'Demo Leader Three','FOFA','','',null,true,'FOFA');
 assert exists(select 1 from public.ambassador_codes where event_id=e and code='FOFA-C'),'Retired codes must never be reassigned';
 assert (public.campus_admin_report(e,null,0)->'ambassadors') is not null,'Authorized admin report must load';
 perform set_config('request.jwt.claim.sub','',true);
 rejected:=false;begin perform public.issue_ambassador_entry(a);exception when others then rejected:=true;end;
 assert rejected,'Unauthenticated admin operations must fail';
 assert (select bool_and(private.tier_value(r.price_tiers,t.pos,'price')=t.price) from public.event_sales_rules r join public.events ev on ev.id=r.event_id cross join (values(1,1000),(50,1000),(51,1200),(100,1200),(101,1300),(120,1300),(121,1400),(150,1400),(151,1500),(200,1500),(201,1700),(220,1700),(221,1800),(250,1800),(251,2000)) t(pos,price) where ev.slug='halloween-party-2026'),'Every price boundary must match';
 assert (select bool_and(private.tier_value(r.discount_tiers,t.pos,'percent')=t.percent) from public.event_sales_rules r join public.events ev on ev.id=r.event_id cross join (values(1,5),(4,5),(5,10),(9,10),(10,20),(14,20),(15,30),(30,30)) t(pos,percent) where ev.slug='halloween-party-2026'),'Every discount boundary must match';
 assert not exists(select 1 from public.bookings where event_id=e and (selections::text like '%dateOfBirth%' or selections::text like '%"gender"%')),'New bookings must not save birth date or gender';
 raise notice 'PASS: price boundaries, quote retry, receipt idempotency, discount tiers, saved totals, commission progression, cancellation, policy acknowledgement without demographics, inactive codes, capacity, free entry and authorization';
end $$;
rollback;
